using Documenter
using DocumenterInterLinks
using Chemostats

# The example pages in `src/examples` are generated by `make_examples.jl`

links = InterLinks(
    "Julia" => "https://docs.julialang.org/en/v1/",
    "QuadGK" => "https://juliamath.github.io/QuadGK.jl/stable/",
    "SciMLBase" => "https://docs.sciml.ai/SciMLBase/stable/",
    "ModelingToolkit" => "https://docs.sciml.ai/ModelingToolkit/stable/",
    "DifferentialEquations" => "https://docs.sciml.ai/DiffEqDocs/stable/",
    "Catalyst" => "https://docs.sciml.ai/Catalyst/stable/",
    "SymbolicIndexingInterface" => "https://docs.sciml.ai/SymbolicIndexingInterface/stable/",
    "StructArrays" => "https://juliaarrays.github.io/StructArrays.jl/stable/",
)

makedocs(
    sitename = "Chemostats.jl",
    modules = [ Chemostats, Chemostats.Trees ],
    format = Documenter.HTML(prettyurls = false),
    repo = Documenter.Remotes.GitHub("kaandocal", "Chemostats.jl"),
    pages = [
        "Home" => "index.md",
        "Usage" => "examples/ribosomes.md",
        "Algorithms" => "alg.md",
        "API" => [ "Chemostats" => "api/chemostats.md", "Cells" => "api/cells.md" ],
        "Examples" => [ "Protein-dependent growth" => "examples/growth_protein.md",
                        "Threshold-triggered division" => "examples/threshold_division.md" ],
        "Theory" => "theory.md",
        "Tree API" => [ "trees/index.md", "trees/trees.md", "trees/analysis.md" ],
    ],
    plugins = [ links ],
    linkcheck = true,
    # bioRxiv blocks automated requests, and github.com often answers CI with 504s
    linkcheck_ignore = [ r"^https://www\.biorxiv\.org/", r"^https://github\.com/" ],
    linkcheck_timeout = 30,
    checkdocs = :public,
)

deploydocs(
    repo = "github.com/kaandocal/Chemostats.jl.git",
    devbranch = "main",
    push_preview = true
)
